import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../core/widgets/states.dart';import '../providers/providers.dart';import '../widgets/content_cards.dart';
class MoviesScreen extends ConsumerStatefulWidget{final String?initialCategory;const MoviesScreen({super.key,this.initialCategory});@override ConsumerState<MoviesScreen>createState()=>_MoviesScreenState();}
class _MoviesScreenState extends ConsumerState<MoviesScreen>{final scroll=ScrollController();@override void initState(){super.initState();scroll.addListener(()=>scroll.position.pixels>scroll.position.maxScrollExtent-500?ref.read(moviesProvider.notifier).load():null);if(widget.initialCategory!=null)WidgetsBinding.instance.addPostFrameCallback((_)=>ref.read(moviesProvider.notifier).load(reset:true,categoryId:widget.initialCategory));}@override Widget build(BuildContext context){final s=ref.watch(moviesProvider);return Scaffold(appBar:AppBar(title:const Text('Kinolar'),actions:[PopupMenuButton<String>(tooltip:'Saralash',onSelected:(value){ref.read(moviesProvider.notifier).load(reset:true,sortBy:value);},itemBuilder:(_)=>const[PopupMenuItem(value:'newest',child:Text('Yangi qo‘shilganlar')),PopupMenuItem(value:'popular',child:Text('Eng mashhur'))])]),body:RefreshIndicator(onRefresh:()=>ref.read(moviesProvider.notifier).load(reset:true),child:s.items.isEmpty&&s.loading?const AppLoading():s.error!=null&&s.items.isEmpty?AppErrorView(message:s.error!,onRetry:()=>ref.read(moviesProvider.notifier).load(reset:true)):GridView.builder(controller:scroll,padding:const EdgeInsets.fromLTRB(16,8,16,30),gridDelegate:const SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent:190,mainAxisExtent:330,crossAxisSpacing:13,mainAxisSpacing:16),itemCount:s.items.length+(s.hasNext?1:0),itemBuilder:(_,i)=>i==s.items.length?const Center(child:CircularProgressIndicator()):MovieCard(movie:s.items[i],width:190))));}@override void dispose(){scroll.dispose();super.dispose();}}
